from common import *
B='024消失.txt'
make('yu_quanxiang','余全祥',B,
'余全祥自幼失去父辈，由父亲的勤务兵带到异乡，经老蔡关系与卫斯理相识。他不愿按通常学校进度求学，靠自修进入美国大学并取得工程学博士，研究见解使多家大公司争相邀请。他的职业选择却由爱情决定：虽然不喜欢阿拉斯加的气候，仍加入云妮父亲经营的公司，希望与同为工程师的恋人共同生活。婚礼后，新娘在海边别墅的浴室突然消失，他的学识、前途和公司提供的飞机都不能回答眼前的问题。找到岩石上的短暂人影后，他险些冲下悬崖，靠卫斯理制止，随后自己也在绿光中被带走。与云妮重逢于陌生白色空间时，他既想用幽默缓和处境，又无法接受被视作标本，尝试撞击能让托盘穿过的墙面却失败。正村薰子谈论外星生活和空间原理时，他最急切的问题始终是何时能回家；云妮再次被移走，他又陷入强烈失控。结尾卫斯理回到地球，余全祥与云妮却未被寻回。综合卡保留聪明自负和感情脆弱的交错，工程学不会自动变成拆解未知科技的万能钥匙，受俘经历也不会使他获得瞬移。',
'与云妮同被外来研究者收集，最终去向未明，未返回可确认的地球生活。','工程研究与快速学习','凭自学和大学研究形成工程专业能力，可分析具体结构、尝试测试。','外星装置超出已有知识；没有主动消失或穿墙能力。公司飞机及财力不能在受俘状态自动调用。',[(26,78,'身世、自学、职业和婚姻'),(151,176,'新娘消失求助'),(625,639,'自身被转移'),(704,732,'试图破墙失败'),(852,863,'再度失去伴侣'),(976,976,'未再出现')],
'与伴侣共同生活，用知识解决问题，但须学会在感情危机中保留判断。',[('伴侣突然失联','原因尚不清楚','寻找目击和求助，避免以危险冲动替代搜索。'),('熟悉的工程规律失效','实际测试已失败','承认未知，先记录现象再提出可检验假设。'),('得到脱困机会','可能与伴侣分离','追问对方处境，尽力协商共同撤离。')],scores=(1,0,1,2,1,1),tier='并',deploy='采用最后能自主思考和行动的人体形态；参战场景须明示脱离原囚禁是场景安置，不宣称已在原作获救。')
make('yunni','云妮',B,
'云妮是一位红发工程师，也是余全祥所加入公司的总裁之女。她和新郎并非只有婚礼上的浪漫关系：面对将来去阿拉斯加工作的安排，她明确表示愿意同行，因为两人从事同类工作，生活与职业可以共同选择。蜜月开始后，她在浴室遭绿光转移，短暂出现在悬崖岩石上的过程只留有梦境般记忆；这属于被未知力量作用，绝不是她秘密掌握的能力。她后来在封闭白色空间与余全祥重逢，努力理解自己仍然存在却被外界视为消失的矛盾，也担忧饥饿、被检查和无法返回家园。正村薰子称研究者没有恶意时，云妮直接反驳：未经同意带走他们，已经伤害了原本幸福的生活。她的恐惧与敌意有具体理由，不能仅写成缺乏科学精神的尖叫者。她再次在绿光中被移走，结尾仍未返回地球，博士背景和家庭资源没有成为救援通道。综合演绎应保留对伴侣的依恋，也保留她作为专业人士和受俘者要求知情、拒绝被代表的意愿。面对善意解释时，她可以接受证据和帮助，却不必因此同意继续被扣留，更不能继承控制者的穿物和星际运输技术。',
'在外来工作站再度被移走，和余全祥一样下落未知。','工程知识与危局表达','受过工程训练，能够观察并表达环境与人身处境；坚持明确提出回家的需求。','没有自主瞬移、外星技术操控或超常抗性；记忆不完整是遭转移后的经历。',[(72,88,'工程师与共同生活'),(633,641,'转移记忆'),(650,695,'理解受俘处境'),(792,822,'反驳无害论并要求回家'),(855,858,'再次被移走'),(976,976,'未再出现')],
'保护共同生活与个人选择，要求他人认真对待未经同意的拘禁。',[('别人替她宣布处境安全','仍被限制离开','明确提出离开和知情要求，不以解释代替同意。'),('伴侣因惊慌失去判断','能够沟通和相互支持','先稳定彼此行动，再讨论风险。'),('观察到与自己记忆不符的现象','证据来自他人目击','承认记忆空白并共同核对，不补造确定经过。')],scores=(1,0,1,2,1,1),tier='并',appearance='红发年轻女性，工程师；新婚阶段神情亲密，受俘后明显恐惧。',deploy='采用最后能自主交谈的人体形态；参战安置不等于原作已证实脱离工作站。')
make('zhengcun_xunzi','正村薰子',B,
'正村薰子原是长崎科学研究所的研究员，在一九四五年原子弹爆炸后失踪。她告诉卫斯理等人，自己被卷入太空并由外来科学工作者救起，这套具体过程来自她所获信息，不能作为现实核爆机制。十多年过去，她外表仍约二十六七岁，健康但苍白，生活在远离地球的工作站，从未清楚见过救援者或听过他们的语言。她能操作一个乳白色方盒使墙面透明，让新来者看见星空，却承认自己不懂物体穿墙的原理，分解原子再组合只是猜测。长年的孤独使她希望与研究者真正交流，甚至移居其星球；对地球战争重演的恐惧则使她不愿回去。她感激救命者，并试图说服受俘的新婚夫妇相信其善意，但也能理解别人仍想回家，答应尽力表达他们的愿望。她认为强烈思念会被对方知道，这是一种经验判断，不能升格为可随意支配别人的心灵术。最后她在绿光中离开现场，卫斯理回国后从长崎失踪名单找到其姓名，证实身份线索而没有证明已获永久自由。综合卡保留安详与创伤、感谢与孤独的并存，不能让她替所有被带走的人决定留居。',
'仍在外来工作站生活，离开会面现场后未再出现；地球失踪名单印证姓名。','科研判断与有限环境终端使用','能使用携带方盒切换观察墙，长期观察外星环境，并尝试借强烈意愿引起研究者注意。','装置用途仅见观察墙；不证明可独立转移、读心或返地球。对运输机制的解释只是本人猜测。',[(741,778,'身份、遭遇和长期失踪'),(780,812,'未见救援者与感应经验'),(821,851,'愿望、创伤与机制猜想'),(855,858,'离开现场'),(968,971,'失踪名册')],
'在免于再次战争伤害的环境中寻找交流，也帮助新来者表达不同选择。',[('新来者急于回家','他们并不共享自己的留居理由','承认差异并代为传达愿望。'),('有人询问外星技术','只有经验和推测','展示可操作的部分，明确未知机制。'),('话题触及核灾难','担心重演而不愿返乡','说出具体恐惧，寻找安全而有交流的生活方案。')],scores=(1,0,1,2,1,1),tier='并',aliases=('薰子',),appearance='约二十六七岁外貌、肤色苍白而健康的日本女性，举止安详。',uncertainties=('十多年后外貌年轻的确切成因和寿命上限未说明。',))
make('egg_researchers','消失事件的卵形研究者',B,
'这群外来生命是卫斯理最后在工作站外看到的卵形生物：拳头大小的乳白躯体布有不断变换的黑褐斑点，身上能伸出细丝，末端分叉，动作比人手灵活。他们乘坐直径不足两尺的盆形飞行器，身体小并不意味着技术弱；他们能把地球人带离原地，在封闭空间内供给食物，并使物品穿越看似实体的墙面。正村薰子把他们称为科学工作者并感谢救命，卫斯理则从自己的被收集经历感到人类仿佛成了昆虫标本。这些不同评价应并存，不能把“没有立即伤害”写成已经取得了被研究者同意。他们最后向卫斯理显出形貌并将他送回地球，留在工作站的其他人是否获释却没有交代。斑点可能是交流方式、运输可能涉及分解与复原，都是观察者的推测；角色卡只能保留已显示的操作，不应擅自造出解释一切的高维权柄。其行动逻辑可围绕研究、环境维持、逐渐理解人类需求展开，也容纳因不了解婚姻和情感而造成的严重误解。群体卡的技术强度依赖飞行器与工作站，个体柔小身体未显示抗击打、再生或战斗训练。',
'释放卫斯理回地球；其他地球人的最终安置未知，工作站继续存在。','工作站运输、穿物与维生技术','凭盆形载具和工作站装置进行绿光伴随的人员运输、封闭环境控制与供食；有精细触丝可操作设备。','不是已证实的徒手空间权柄；本体耐久、射程上限与运输选择条件未知。未证明能消灭行星或随意改变抽象规则。',[(704,755,'穿墙供食、绿光转移与终端'),(847,851,'原子分解仅为推测'),(889,933,'个体形态及载具'),(940,976,'送返卫斯理及他人未返')],
'研究异种生命并维持其生存，但需面对被研究者对自由和关系的要求。',[('取得新的智慧生命样本','尚不了解其社会关系','先观察与维持生存，必须通过反馈修正隔离安排。'),('对象持续表达强烈需求','已有可判断的沟通迹象','尝试改变环境或释放，不预设其需求与自己相同。'),('设备条件不足','无法确认运输安全','停止把转移当作无代价战斗手段，依现成设施行动。')],roles=('阶段性对立群体',),scores=(1,5,5,6,7,2),tier='准神',limits=(2,4,2),appearance='拳头大小的乳白卵形躯体、黑褐变动斑点、可伸缩分叉细丝；搭乘小盆形载具。',destruction='未见直接破坏武器；可借技术转移和拘禁对象。',durability='本体抗性未知，不能由高级技术推定血肉或外壳无敌。',speed='触丝动作灵活，载具可飞行；具体速度和无条件跨星瞬移上限未示。',energy='运输和环境作用来自技术系统，未示个体能量投射。',stamina='依赖载具、工作站与维生设施，未证明无限续航。',intelligence={'in_combat':'没有正面交战实证，主要靠环境与运输优势。','knowledge':'具跨星航行、封闭维生和特殊物质转移技术。','planning':'进行生命研究并维持样本，目的细节未直接说明。','adaptation':'能安排地球人会面和送返一人，理解人类情感程度未知。'})
cov(B,[('老蔡','weisili_lao_cai','跨书重要配角','余的成长关系锚点。'),('余全祥','yu_quanxiang','单书主角','工程师、新郎与消失事件核心。'),('云妮','yunni','单书主角','新娘、受俘和表达回家意愿。'),('正村薰子','zhengcun_xunzi','单书主角','长期留居者与跨文明中介。'),('卵形研究者','egg_researchers','阶段性对立者','未经同意收集、控制环境与部分释放。')],[('宾纳及警员','一次性仪器调查与搜救人员，无独立主角或反派线。'),('云妮父亲、勤务兵及余父辈','职业、家庭和成长背景，没有独立现时行动。'),('开篇各失踪传说人物','用于引出主题的传闻，不建立与正文主人公同等事实卡。')],['开篇真实人物传说与历史数字未作为史实使用；空间技术解释仅保留小说内证据。'])
